export const ITEMS={jug_empty:{name:'Пустой кувшин',atlas:'0% 0%'},jug_water:{name:'Кувшин с водой',atlas:'100% 0%'},mary_ale:{name:'Эль Мэри',atlas:'0% 100%'},sword:{name:'Меч',slot:0,icon:'⚔',color:'#c5d5dd'},bow:{name:'Лук',slot:0,icon:'➶',color:'#b58c50'},mage:{name:'Посох',slot:0,icon:'✦',color:'#ff9952'},arrow:{name:'Стрелы',icon:'➶',color:'#c9c1a5'},carcass:{name:'Туша кролика',icon:'◆',color:'#c68b83'},fang:{name:'Клык волка',icon:'◢',color:'#e8dfbf'}};
export const SLOT_NAMES=['Оружие','Доп. оружие / щит','Шлем','Нагрудник','Штаны','Обувь'];
export function createInventory(){return Array(18).fill(null)}
export function addItem(slots,id,count=1){const same=slots.findIndex((s,i)=>i>=6&&s?.id===id);const index=same>=0?same:slots.findIndex((s,i)=>i>=6&&!s);if(index<0)return false;if(slots[index])slots[index].count+=count;else slots[index]={id,count};return true}
export function countItem(slots,id){return slots.reduce((n,s)=>n+(s?.id===id?s.count:0),0)}
export function removeItem(slots,id,count=1){if(countItem(slots,id)<count)return false;for(let i=0;i<slots.length&&count;i++){if(slots[i]?.id!==id)continue;const take=Math.min(count,slots[i].count);slots[i].count-=take;count-=take;if(!slots[i].count)slots[i]=null}return true}
export function moveItem(slots,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=18||to>=18||from===to||!slots[from])return false;const fits=(item,index)=>!item||index>=6||ITEMS[item.id]?.slot===index;if(!fits(slots[from],to)||!fits(slots[to],from))return false;if(slots[to]?.id===slots[from].id&&to>=6){slots[to].count+=slots[from].count;slots[from]=null}else [slots[from],slots[to]]=[slots[to],slots[from]];return true}
export function itemIcon(id){if(ITEMS[id]?.atlas)return '<span class="item-art" style="background-position:'+ITEMS[id].atlas+'"></span>'; const shapes={sword:'<path d="M27 4L34 4L33 40L26 40Z" fill="#c5d5dd"/><path d="M18 40H41M30 42V57" stroke="#bb9858" stroke-width="5"/>',bow:'<path d="M19 6Q57 32 19 58" fill="none" stroke="#b58c50" stroke-width="5"/><path d="M19 6V58M8 32H48L41 27M48 32L41 37" fill="none" stroke="#e1d5ae" stroke-width="2"/>',mage:'<path d="M30 22V58" stroke="#98724a" stroke-width="6"/><path d="M30 4L40 17L30 29L20 17Z" fill="#ff9952"/>',arrow:'<path d="M15 52L46 12M46 12L34 17M46 12L44 25M15 52L13 40M15 52L27 49" stroke="#dbd0a9" stroke-width="3" fill="none"/>',carcass:'<ellipse cx="31" cy="33" rx="17" ry="12" fill="#bc827b"/><ellipse cx="46" cy="24" rx="8" ry="7" fill="#c89c88"/><path d="M43 19L38 7M49 18L49 6M19 37L11 48M34 41L39 50" stroke="#c89c88" stroke-width="6"/>',fang:'<path d="M20 8Q48 6 42 29Q36 48 15 57Q30 34 20 8" fill="#e8dfbf"/><path d="M20 8Q32 18 44 16" stroke="#9e947d" fill="none"/>'};return '<svg viewBox="0 0 64 64" width="48" height="48" aria-hidden="true">'+shapes[id]+'</svg>'}
